package com.autoops.conversation.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="conversation_messages")public class ConversationMessage{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="conversation_id",nullable=false)private Long conversationId;@Column(nullable=false)private String role;@Column(nullable=false,columnDefinition="text")private String content;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();}
